use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/three-lane-final-exp176";
const OLD:&str="/home/ubuntu/src/zopro-perf-work/three-lane-miller176";
const ARMS:[&str;4]=["native","fresh","packed","fully"];
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){assert!(!p.as_ref().exists());fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn step(name:impl Into<String>,argv:Vec<String>)->Value{json!({"kind":"command","name":name.into(),"argv":argv,"timeout_seconds":300,"environment":{"LC_ALL":"C"}})}
fn add(arm:&str,w:usize,block:usize,panel:&str,jobs:&mut Vec<Value>,steps:&mut Vec<Value>){
 let name=format!("{panel}-b{block}-full-w{w}-{arm}");let rounds=match panel{"preflight"=>1,"latency"=>101,_=>8192};let mut argv=vec![];let mut data=None;
 if panel=="stat"||panel=="profile"{
  argv.extend(["sudo".into(),"-n".into(),"env".into(),"LC_ALL=C".into(),format!("ZOPRO_BENCH_PERF_CTL={}",r("ctl").display()),format!("ZOPRO_BENCH_PERF_ACK={}",r("ack").display()),"perf".into()]);
  if panel=="stat"{let p=r(format!("stat/{name}.csv"));argv.extend(["stat".into(),"--no-big-num".into(),"-x".into(),";".into(),"-e".into(),"{cycles:u,instructions:u}".into(),"-e".into(),"page-faults,context-switches".into(),"-o".into(),p.display().to_string()]);data=Some(p);}
  else{let p=r(format!("perf/{name}.data"));argv.extend(["record".into(),"--no-buildid-cache".into(),"--sample-cpu".into(),"--timestamp".into(),"-P".into(),"-e".into(),"cycles:u".into(),"-c".into(),"4000000".into(),"-m".into(),"512".into(),"-o".into(),p.display().to_string()]);data=Some(p);}
  argv.extend(["--delay=-1".into(),format!("--control=fifo:{},{}",r("ctl").display(),r("ack").display()),"--".into()]);
 }
 argv.extend(["taskset".into(),"-c".into(),if w==1{"2".into()}else{format!("0-{}",w-1)},r("bench").display().to_string(),arm.into(),"full".into(),w.to_string(),rounds.to_string()]);steps.push(step(&name,argv));jobs.push(json!({"name":name,"arm":arm,"endpoint":"full","workers":w,"block":block,"panel":panel,"rounds":rounds,"data":data}));
}
fn prepare(){
 assert_eq!(read(r("qualification.json"))["passed"],true);let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("qualification-pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}
 for p in [r("bench.rs"),r("bench"),r("setup-bench.rs"),r("bench-copy-review.txt"),r("timing-design.md"),r("campaign.rs"),r("campaign"),r("publish.rs"),r("publish"),r("qualification.json"),r("qualification-runs/packed-complete-final-exponentiation-qualification/exit.json"),PathBuf::from("/home/ubuntu/src/zopro-perf-work/g2-last-finisher-query176/perf_support.rs")]{pins.insert(p.display().to_string(),hash(&p));}
 for(program,args,name)in[("nm",vec!["-S","-C","--defined-only"],"bench.nm"),("objdump",vec!["-d","-C"],"bench.asm")]{let o=Command::new(program).args(args).arg(r("bench")).output().unwrap();assert!(o.status.success());fs::write(r(name),o.stdout).unwrap();pins.insert(r(name).display().to_string(),hash(r(name)));}
 let asm=fs::read_to_string(r("bench.asm")).unwrap();assert!(asm.contains("madd52")&&asm.contains("final_exponentiation")&&asm.contains("%zmm"));
 for d in["stat","perf"]{fs::create_dir(r(d)).unwrap();}for n in["ctl","ack"]{assert!(Command::new("mkfifo").args(["-m","600"]).arg(r(n)).status().unwrap().success());}assert!(Command::new("sudo").args(["-n","true"]).status().unwrap().success());
 let(mut jobs,mut steps)=(vec![],vec![]);for w in[1,16,32]{for arm in ARMS{add(arm,w,0,"preflight",&mut jobs,&mut steps);}}steps.push(step("check-preflights",vec![r("campaign").display().to_string(),"preflights".into()]));
 for block in 0..31{let mut order=[1,16,32];order.rotate_left(block%3);let mut arms=ARMS;arms.rotate_left(block%4);if block%2!=0{order.reverse();arms.reverse();}for w in order{for arm in arms{add(arm,w,block,"latency",&mut jobs,&mut steps);}}}
 for panel in["stat","profile"]{for(arm,w)in[("native",1),("fully",1),("native",32),("fresh",32),("packed",32),("fully",32)]{add(arm,w,0,panel,&mut jobs,&mut steps);}}
 let uid=Command::new("id").arg("-u").output().unwrap();let gid=Command::new("id").arg("-g").output().unwrap();assert!(uid.status.success()&&gid.status.success());let owner=format!("{}:{}",String::from_utf8(uid.stdout).unwrap().trim(),String::from_utf8(gid.stdout).unwrap().trim());
 for j in jobs.iter().filter(|j|j["data"].is_string()){let n=j["name"].as_str().unwrap();let data=j["data"].as_str().unwrap();steps.push(step(format!("own-{n}"),vec!["sudo".into(),"-n".into(),"chown".into(),owner.clone(),data.into()]));}
 for j in jobs.iter().filter(|j|j["panel"]=="profile"){let n=j["name"].as_str().unwrap();let data=j["data"].as_str().unwrap();steps.push(step(format!("report-{n}"),vec!["perf".into(),"report".into(),"--stdio".into(),"--no-children".into(),"--percent-limit".into(),"0".into(),"--sort".into(),"dso,symbol".into(),"-i".into(),data.into()]));steps.push(step(format!("samples-{n}"),vec!["perf".into(),"script".into(),"-i".into(),data.into(),"-F".into(),"comm,pid,tid,cpu,time,event,period,ip,sym,dso".into()]));steps.push(step(format!("raw-{n}"),vec!["perf".into(),"script".into(),"-D".into(),"-i".into(),data.into()]));}
 save(r("jobs.json"),&json!(jobs));save(r("capture-pins.json"),&json!(pins));save(r("capture-plan.json"),&json!({"version":1,"source_pins":r("capture-pins.json"),"steps":steps}));println!("Prepared {} jobs/{}commands/{}pins, no timed call yet",jobs.len(),steps.len(),pins.len());
}
fn output(j:&Value)->Value{
 let n=j["name"].as_str().unwrap();let base=r(format!("capture/{n}"));let e=read(base.join("exit.json"));assert_eq!(e["success"],true);for(s,k)in[("stdout.log","stdout_sha256"),("stderr.log","stderr_sha256")]{assert_eq!(hash(base.join(s)),e[k].as_str().unwrap());}
 let row:Value=serde_json::from_str(fs::read_to_string(base.join("stdout.log")).unwrap().trim()).unwrap();for k in["arm","endpoint","workers","rounds"]{assert_eq!(row[k],j[k]);}assert_eq!(row["primes"],7);assert_eq!(row["checked_outputs"],j["rounds"]);assert_eq!(row["worker_pins"].as_array().unwrap().len(),j["workers"].as_u64().unwrap()as usize);let mut ns=row["samples_ns"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).collect::<Vec<_>>();assert_eq!(ns.len(),j["rounds"].as_u64().unwrap()as usize);ns.sort_unstable();assert_eq!(row["median_ns"],ns[ns.len()/2]);row
}
fn preflights(){let mut digests=BTreeSet::new();for j in read(r("jobs.json")).as_array().unwrap().iter().filter(|j|j["panel"]=="preflight"){digests.insert(output(j)["output_sha256"].as_str().unwrap().to_string());}assert_eq!(digests.len(),1);save(r("preflights.json"),&json!({"passed":true,"processes":12,"cached_full_outputs_match":true}));println!("All12 optimized complete-consumer preflights match the reused oracle");}
fn ci(mut values:Vec<f64>)->Value{assert_eq!(values.len(),31);let wins=values.iter().filter(|&&v|v<1.).count();values.sort_by(f64::total_cmp);json!({"low":values[9],"median":values[15],"high":values[21],"wins":wins})}
fn finish(){
 assert_eq!(read(r("capture/result.json"))["status"],"complete");for(p,h)in read(r("capture-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let jobs=read(r("jobs.json"));let jobs=jobs.as_array().unwrap();let mut table=BTreeMap::new();let mut observations=vec![];for j in jobs{let row=output(j);if j["panel"]=="latency"{table.insert((j["workers"].as_u64().unwrap()as usize,j["arm"].as_str().unwrap().to_string(),j["block"].as_u64().unwrap()as usize),row["median_ns"].as_u64().unwrap()as f64);}observations.push(json!({"job":j,"observation":row}));}
 let at=|w:usize,arm:&str,b:usize|table[&(w,arm.to_string(),b)];let mut failures=vec![];let mut contexts=vec![];let mut aggregate=BTreeMap::from([("native",vec![0f64;31]),("fresh",vec![0f64;31]),("packed",vec![0f64;31])]);
 for w in[1usize,16,32]{let cal=ci((0..31).map(|b|at(w,"fresh",b)/at(w,"native",b)).collect());if cal["low"].as_f64().unwrap()<1./1.03||cal["high"].as_f64().unwrap()>1.03{failures.push(format!("calibration w{w}"));}let mut row=json!({"workers":w,"fresh_native_calibration":cal});for arm in ARMS{let mut v=(0..31).map(|b|at(w,arm,b)).collect::<Vec<_>>();v.sort_by(f64::total_cmp);row[format!("{arm}_median_ns")]=json!(v[15]);}
  for control in["native","fresh","packed"]{let values=(0..31).map(|b|at(w,"fully",b)/at(w,control,b)).collect::<Vec<_>>();for b in 0..31{aggregate.get_mut(control).unwrap()[b]+=values[b].ln()/3.;}let ratio=ci(values);if ratio["high"].as_f64().unwrap()>1.03{failures.push(format!("nonregression w{w}/{control}"));}if w==32&&(ratio["high"].as_f64().unwrap()>=1.||ratio["wins"].as_u64().unwrap()<21){failures.push(format!("gain w32/{control}"));}row[format!("fully_{control}")]=ratio;}contexts.push(row);
 }
 let mut aggregates=json!({});for control in["native","fresh","packed"]{let result=ci(aggregate.remove(control).unwrap().into_iter().map(f64::exp).collect());if result["high"].as_f64().unwrap()>=1.||result["wins"].as_u64().unwrap()<21{failures.push(format!("gain all3/{control}"));}aggregates[control]=result;}
 let mut profiles=vec![];for j in jobs.iter().filter(|j|j["panel"]=="profile"){let n=j["name"].as_str().unwrap();let raw=fs::read_to_string(r(format!("capture/raw-{n}/stdout.log"))).unwrap();let samples=fs::read_to_string(r(format!("capture/samples-{n}/stdout.log"))).unwrap();let lost=raw.lines().filter(|l|l.contains("PERF_RECORD_LOST")).count();let lines=samples.lines().filter(|l|l.contains("cycles:u")).collect::<Vec<_>>();let unknown=lines.iter().filter(|l|l.contains("[unknown]")).count();profiles.push(json!({"job":n,"samples":lines.len(),"unknown_samples":unknown,"unknown_fraction":unknown as f64/lines.len().max(1)as f64,"lost_records":lost,"zero_lost":lost==0,"at_least_1000_samples":lines.len()>=1000,"data_sha256":hash(j["data"].as_str().unwrap()),"report":format!("capture/report-{n}/stdout.log"),"parser_scope":"single stream counter; no independent exact ELF/IP/loss parser"}));}
 save(r("observations.json"),&json!(observations));save(r("analysis.json"),&json!({"gate_passed":failures.is_empty(),"failed_checks":failures,"contexts":contexts,"all3":aggregates,"profiles":profiles,"complete_component_processes":jobs.len(),"new_SDK_requests":0,"new_proofs":0,"new_full_proof_timings":0,"production_changed":false,"candidate_adopted":false,"old_study_gate_passed":false,"proof_ledger_count":31387}));println!("New fully-packed caller gate={}, failedchecks={}",failures.is_empty(),failures.len());
}
fn main(){match std::env::args().nth(1).as_deref(){Some("prepare")=>prepare(),Some("preflights")=>preflights(),Some("finish")=>finish(),_=>panic!("prepare | preflights | finish")}}
